set-variable.value:
@{
      try {
        var settings = JObject.Parse((string)context.Variables["documentSettings"]);
        var model = (string)context.Variables["documentModel"];
        if (context.Request.Url.Query.Count != 1 || !context.Request.Url.Query.ContainsKey("model") || context.Request.Url.Query["model"].Length != 1 || !((JArray)settings["allowedModels"]).Any(m => (string)m == model)) { return 400; }
        if (context.Request.Headers.GetValueOrDefault("Content-Encoding", "identity") != "identity") { return 415; }
        var mime = context.Request.Headers.GetValueOrDefault("Content-Type", "").Split(';')[0].Trim().ToLowerInvariant();
        if (!((JArray)settings["contentTypes"]).Any(t => (string)t == mime)) { return 415; }
        if (context.Request.Body == null) { return 400; }
        var bytes = context.Request.Body.As<byte[]>(preserveContent: true);
        if (bytes.Length > (int)settings["maxRequestBytes"]) { return 413; }
        if (bytes.Length < 8) { return 400; }
        var pdf = bytes[0] == 37 && bytes[1] == 80 && bytes[2] == 68 && bytes[3] == 70 && bytes[4] == 45;
        var jpeg = bytes[0] == 255 && bytes[1] == 216 && bytes[2] == 255;
        var png = bytes[0] == 137 && bytes[1] == 80 && bytes[2] == 78 && bytes[3] == 71 && bytes[4] == 13 && bytes[5] == 10 && bytes[6] == 26 && bytes[7] == 10;
        var tiff = (bytes[0] == 73 && bytes[1] == 73 && bytes[2] == 42 && bytes[3] == 0) || (bytes[0] == 77 && bytes[1] == 77 && bytes[2] == 0 && bytes[3] == 42);
        var bmp = bytes[0] == 66 && bytes[1] == 77;
        return ((mime == "application/pdf" && pdf) || (mime == "image/jpeg" && jpeg) || (mime == "image/png" && png) || (mime == "image/tiff" && tiff) || (mime == "image/bmp" && bmp)) ? 200 : 400;
      } catch { return 400; }
    }

@{
      try {
        var response = context.Variables["documentStartResponse"] as IResponse;
        if (response == null || response.StatusCode != 202) { return ""; }
        /* UriKindはAPIM式の許可型ではないため、文字列のみのコンストラクターを使います。 */
        var baseUrl = (string)context.Variables["documentBaseUrl"];
        var location = new Uri(response.Headers.GetValueOrDefault("Operation-Location", ""));
        var expected = new Uri(baseUrl);
        var prefix = "/documentintelligence/documentModels/" + (string)context.Variables["documentModel"] + "/analyzeResults/";
        if (location.Scheme != "https" || !String.Equals(location.Authority, expected.Authority, StringComparison.OrdinalIgnoreCase) || location.UserInfo.Length != 0 || location.Fragment.Length != 0 || !location.AbsolutePath.StartsWith(prefix, StringComparison.Ordinal) || location.Query != "?api-version=2024-11-30") { return ""; }
        Guid id;
        if (!Guid.TryParseExact(location.AbsolutePath.Substring(prefix.Length), "D", out id)) { return ""; }
        return baseUrl + prefix + id.ToString("D") + "?api-version=2024-11-30";
      } catch { return ""; }
    }

@{
      var response = context.Variables["documentStartResponse"] as IResponse;
      if (response == null) { return 504; }
      if (response.StatusCode == 429) { return 429; }
      if (response.StatusCode == 400 || response.StatusCode == 415 || response.StatusCode == 422) { return 422; }
      return String.IsNullOrEmpty((string)context.Variables["documentPollUrl"]) ? 502 : 504;
    }

@{
          var state = "failed"; var status = 502; var result = "";
          try {
            var response = context.Variables["documentPollResponse"] as IResponse;
            if (response == null) { status = 504; }
            else if (response.StatusCode == 429) { status = 429; }
            else if (response.StatusCode == 200) {
              var settings = JObject.Parse((string)context.Variables["documentSettings"]);
              var bytes = response.Body.As<byte[]>(preserveContent: true);
              if (bytes.Length <= (int)settings["maxResponseBytes"]) {
                var body = response.Body.As<JObject>();
                var current = (string)body?["status"];
                if (current == "running" || current == "notStarted") { state = "running"; status = 504; }
                else if (current == "failed" || current == "canceled") { status = 422; }
                else if (current == "succeeded") {
                  var analysis = body["analyzeResult"] as JObject;
                  if (analysis != null && (string)analysis["apiVersion"] == (string)settings["apiVersion"] && (string)analysis["modelId"] == (string)context.Variables["documentModel"] && analysis["content"]?.Type == JTokenType.String && analysis["pages"] is JArray) {
                    state = "succeeded"; status = 200;
                    result = new JObject(new JProperty("analyzeResult", analysis), new JProperty("requestId", context.RequestId.ToString())).ToString(Newtonsoft.Json.Formatting.None);
                  }
                }
              }
            }
          } catch { state = "failed"; status = 502; }
          return new JObject(new JProperty("state", state), new JProperty("status", status), new JProperty("result", result)).ToString(Newtonsoft.Json.Formatting.None);
        }
